# >>> STATIC
_static_secureErase_level() {
    cat <<-'ARGCEOF'
	0	Single-pass zero fill erase
	1	Single-pass random fill erase
	2	Seven-pass erase, consisting of zero fills and all-ones fills plus a final random fill
	3	Gutmann algorithm 35-pass erase
	4	Three-pass erase, consisting of two random fills plus a final zero fill
ARGCEOF
}

_static_partitionDisk_scheme() {
    cat <<-'ARGCEOF'
	APM	specifies that an Apple Partition Map scheme should be used
	APMFormat	specifies that an Apple Partition Map scheme should be used
	MBR	specifies that a Master Boot Record scheme should be used
	MBRFormat	specifies that a Master Boot Record scheme should be used
	GPT	specifies that a GUID Partitioning Table scheme should be used
	GPTFormat	specifies that a GUID Partitioning Table scheme should be used
ARGCEOF
}

_static_resizeVolume_mode() {
    cat <<-'ARGCEOF'
	limits	Specifying limits instead of size takes no action, but instead prints the range of valid values for the target partition, taking into account current file system and partition map conditions such as files in use and other (immovable) partitions following the target
	mapsize	Specifying mapsize instead of size takes no action, but instead prints the size of the encompassing whole-disk device, as well as the size of the entire partition map (all partitions less map overhead)
	R	You can grow a volume (partition) (back) to its maximum size possible, provided no new partitions have been created that are in the way, by specifying R for the new volume size
	size	Non-destructively resize a volume (partition); you may increase or decrease its size
ARGCEOF
}

_static_appleRAID_update_key() {
    cat <<-'ARGCEOF'
	AutoRebuild	If true, the system attempts to rebuild degraded mirrored volumes automatically
	SetTimeout	Controls how long the system waits (in seconds) for a missing device before degrading a mirrored raid set
ARGCEOF
}

_static_apfs_resizeContainer_size() {
    cat <<-'ARGCEOF'
	limits	causes no action to be taken, but instead prints a range of valid values
	size	
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_apfs_role() {
    printf '%s\n' B R V I T S D E X H C Y
}

_choice_apfs_user() {
    printf '%s\n' disk
}

_choice_device() {
    _choice_disk
    _choice_volume
}

_choice_disk() {
    diskutil list 2>/dev/null | gawk '
        {
            for (i = NF; i > 0; i--) {
                if ($i ~ /^disk[0-9]+(s[0-9]+)*$/) { print $i; break }
            }
        }
    '
}

_choice_diskutil_format() {
    diskutil listFilesystems 2>/dev/null | gawk '
        /^PERSONALITY/ { in_table = 1; next }
        !in_table { next }
        /^[[:space:]]*\(or\)/ {
            line = $0
            sub(/^[[:space:]]*\(or\)[[:space:]]*/, "", line)
            sub(/[[:space:]][[:space:]].*$/, "", line)
            if (line ~ /[[:alpha:]]/) print line
            next
        }
        /^[[:space:]]/ { next }
        {
            line = $0
            sub(/[[:space:]][[:space:]].*$/, "", line)
            if (line ~ /[[:alpha:]]/) print line
        }
    '
}

_choice_volume() {
    find /Volumes -mindepth 1 -maxdepth 1 -print 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
